-- Importação do cardápio da Marmitaria Central (dados copiados do cardápio Anota AI da própria loja)
begin;
update loja set nome = 'Marmitaria Central', descricao = 'Marmitas caseiras todos os dias',
  endereco = 'Rua Italo Ado Fontanini, 1264 - Loteamento Biguaçu, Apucarana - PR, 86809-015',
  logo_url = 'https://client-assets.anota.ai/establishment-logos/68557c5b74b79a001911f6e71789656286153blob', pedido_minimo = 0, tempo_entrega = '30 a 50 min', tempo_retirada = '15 min',
  aceita_entrega = true, aceita_retirada = true, aceita_dinheiro = true, aceita_cartao_entrega = true, aceita_pix_entrega = true,
  aceita_pix_online = false, aceita_cartao_online = false, horario_automatico = true,
  mensagem_fechada = 'Atendemos de segunda a sábado, das 10h10 às 13h40.' where id = 1;
delete from horarios;
do $$
declare c1 uuid; c2 uuid; c3 uuid; p uuid; g uuid;
begin
end $$;
commit;
select (select count(*) from categorias) categorias, (select count(*) from produtos) produtos, (select count(*) from grupos_adicionais) grupos, (select count(*) from opcoes_adicionais) opcoes, (select count(*) from horarios) horarios, (select nome from loja) loja;
